function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);const ox=shake?(Math.random()-.5)*shake:0,oy=shake?(Math.random()-.5)*shake:0;ctx.save();ctx.translate(ox,oy);drawGrid();drawPath();drawUnits();drawShots();drawParticles();drawFloats();drawEffects();ctx.restore()}
function drawGrid(){const s=grid.size;for(const c of cells){const p=cellCenter(c.x,c.y),occupied=towers.some(t=>t.x===c.x&&t.y===c.y);rounded(p.x-s*.43,p.y-s*.43,s*.86,s*.86,s*.16);ctx.fillStyle=occupied?'#10252c66':'#17313b35';ctx.fill();ctx.strokeStyle=occupied?'#31535a55':'#8bbcc01b';ctx.lineWidth=1;ctx.stroke();if(hoverCell&&hoverCell.x===c.x&&hoverCell.y===c.y){const d=selectedType&&defs.find(t=>t.id===selectedType),ok=!!d&&money>=d.cost&&!occupied;ctx.fillStyle=ok?'#69e7d425':'#ff718f1d';ctx.fill();ctx.strokeStyle=ok?'#69e7d7a8':'#ff718fa8';ctx.lineWidth=1.5;ctx.stroke();if(d&&ok){const r=d.range;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle='#56e4d009';ctx.fill();ctx.strokeStyle='#56e4d04b';ctx.setLineDash([5,6]);ctx.stroke();ctx.setLineDash([])}}}}
function drawPath(){const s=grid.size;ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();path.forEach((v,i)=>{const x=grid.left+(v[0]+.5)*s,y=grid.top+(v[1]+.5)*s;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle='#071219';ctx.lineWidth=s*.75;ctx.stroke();ctx.strokeStyle='#132b32';ctx.lineWidth=s*.65;ctx.stroke();ctx.strokeStyle='#24504e';ctx.lineWidth=1;ctx.setLineDash([5,8]);ctx.stroke();ctx.setLineDash([]);ctx.restore();for(let i=0;i<path.length-1;i++){const a=path[i],b=path[i+1];if(a[1]===b[1]){const x1=grid.left+(Math.min(a[0],b[0])+.5)*s,x2=grid.left+(Math.max(a[0],b[0])+.5)*s,y=grid.top+(a[1]+.5)*s;for(let x=x1+20;x<x2-10;x+=38){ctx.fillStyle='#335c5d';ctx.beginPath();ctx.arc(x,y,1.3,0,Math.PI*2);ctx.fill()}}}const start=posAt(0),end=posAt(pathLength());drawBeacon(start.x,start.y,'IN',true);drawBeacon(end.x,end.y,'CORE',false)}
function drawBeacon(x,y,label,start){const pulse=.5+.5*Math.sin(clock*3);ctx.save();ctx.translate(x,y);ctx.strokeStyle=start?'#60e8d1':'#ff758e';ctx.globalAlpha=.4+pulse*.45;ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,12+pulse*5,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle=start?'#78f0d7':'#ff728e';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=14;ctx.beginPath();ctx.arc(0,0,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#a5bec0';ctx.font='800 7px system-ui';ctx.textAlign='center';ctx.fillText(label,0,-18);ctx.restore()}
function drawUnits(){for(const t of towers){const p=cellCenter(t.x,t.y),d=defs.find(x=>x.id===t.type),r=grid.size*.31;ctx.save();if(t===selectedTower){ctx.beginPath();ctx.arc(p.x,p.y,t.range,0,Math.PI*2);ctx.fillStyle='#59e4d508';ctx.fill();ctx.strokeStyle='#72eedb54';ctx.setLineDash([5,6]);ctx.stroke();ctx.setLineDash([])}ctx.translate(p.x,p.y);ctx.fillStyle='#07131ddd';ctx.beginPath();ctx.ellipse(0,r*.78,r*.78,r*.36,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=d.color;ctx.globalAlpha=.16;ctx.beginPath();ctx.arc(0,0,r*1.35,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=d.color;ctx.lineWidth=1.5;ctx.globalAlpha=.75;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#132d37';ctx.beginPath();ctx.arc(0,0,r*.73,0,Math.PI*2);ctx.fill();ctx.strokeStyle=d.color;ctx.lineWidth=2;ctx.stroke();ctx.rotate(t.angle);ctx.fillStyle=d.color;rounded(-r*.31,-r*.23,r*.9,r*.46,r*.14);ctx.fill();ctx.beginPath();ctx.arc(r*.42,0,r*.2,0,Math.PI*2);ctx.fillStyle='#e7ffff';ctx.shadowColor=d.color;ctx.shadowBlur=8;ctx.fill();ctx.shadowBlur=0;ctx.restore();if(t.level>1){ctx.fillStyle='#c9f276';ctx.font='900 8px system-ui';ctx.textAlign='center';ctx.fillText(`◆${t.level}`,p.x,p.y-r-4)}}
 for(const e of enemies){const p=posAt(e.distance),pulse=1+Math.sin(clock*7+e.seed)*.08;ctx.save();ctx.translate(p.x,p.y);ctx.scale(pulse,pulse);const color=e.kind==='brute'?'#ff718f':e.kind==='dash'?'#bd8aff':'#f29a70';ctx.shadowColor=color;ctx.shadowBlur=e.kind==='brute'?15:8;ctx.fillStyle=e.hit>0?'#ffffff':color;if(e.kind==='brute'){ctx.rotate(Math.PI/4);rounded(-e.radius*.72,-e.radius*.72,e.radius*1.44,e.radius*1.44,4);ctx.fill();ctx.rotate(-Math.PI/4)}else if(e.kind==='dash'){ctx.beginPath();ctx.moveTo(0,-e.radius);ctx.lineTo(e.radius*.85,0);ctx.lineTo(0,e.radius);ctx.lineTo(-e.radius*.85,0);ctx.closePath();ctx.fill()}else{ctx.beginPath();ctx.arc(0,0,e.radius,0,Math.PI*2);ctx.fill()}ctx.shadowBlur=0;ctx.fillStyle='#17232b';ctx.beginPath();ctx.arc(-e.radius*.28,-1,1.6,0,Math.PI*2);ctx.arc(e.radius*.28,-1,1.6,0,Math.PI*2);ctx.fill();ctx.restore();const bw=e.radius*2.5,bh=3;ctx.fillStyle='#17282e';rounded(p.x-bw/2,p.y-e.radius-8,bw,bh,2);ctx.fill();ctx.fillStyle=e.hp/e.maxHp<.3?'#ff7488':'#85e89a';rounded(p.x-bw/2,p.y-e.radius-8,bw*clamp(e.hp/e.maxHp,0,1),bh,2);ctx.fill()}}
function drawShots(){for(const s of shots){ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.globalAlpha=.55;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x-6,s.y+5);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#efffff';ctx.shadowColor=s.color;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(s.x,s.y,2.4,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}}
function drawParticles(){for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size*clamp(p.life*3,.2,1),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function drawFloats(){ctx.textAlign='center';ctx.font='900 10px system-ui';for(const f of floaters){ctx.globalAlpha=clamp(f.life,0,1);ctx.fillStyle=f.color;ctx.shadowColor='#081319';ctx.shadowBlur=4;ctx.fillText(f.text,f.x,f.y);ctx.shadowBlur=0}ctx.globalAlpha=1}
function drawEffects(){const grad=ctx.createRadialGradient(W*.5,H*.48,Math.min(W,H)*.2,W*.5,H*.48,Math.max(W,H)*.65);grad.addColorStop(0,'#00000000');grad.addColorStop(1,'#02080c73');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);if(paused){ctx.fillStyle='#06121955';ctx.fillRect(0,0,W,H)}}
function frame(ts){const dt=Math.min(.04,(ts-last)/1000||0);last=ts;update(dt);draw();requestAnimationFrame(frame)}
function pointer(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
canvas.addEventListener('pointermove',e=>{const p=pointer(e),x=Math.floor((p.x-grid.left)/grid.size),y=Math.floor((p.y-grid.top)/grid.size);hoverCell=x>=0&&y>=0&&x<grid.cols&&y<grid.rows?{x,y}:null});canvas.addEventListener('pointerleave',()=>hoverCell=null);canvas.addEventListener('pointerdown',e=>{if(e.button===2){selectedType=null;refreshSelection();return}const p=pointer(e),x=Math.floor((p.x-grid.left)/grid.size),y=Math.floor((p.y-grid.top)/grid.size);if(x<0||y<0||x>=grid.cols||y>=grid.rows)return;if(selectedType)makeTower(selectedType,x,y);else selectAt(p.x,p.y)});canvas.addEventListener('contextmenu',e=>e.preventDefault());
document.getElementById('startWave').onclick=startWave;document.getElementById('upgradeBtn').onclick=doUpgrade;document.getElementById('sellBtn').onclick=doSell;document.getElementById('closeSel').onclick=()=>{selectedTower=null;refreshSelection()};document.getElementById('pauseBtn').onclick=()=>{if(gameOver)return;paused=!paused;document.getElementById('pauseBtn').classList.toggle('active',paused);document.getElementById('pauseBtn').textContent=paused?'▶':'Ⅱ';updateUI();if(paused)toast('Simulation paused');else toast('Simulation resumed')};
let audio=null,soundOn=true;function sound(type){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain(),now=audio.currentTime;const notes={place:[550,.07,'sine'],upgrade:[720,.12,'triangle'],fire:[370,.045,'sine'],spawn:[145,.08,'triangle'],pop:[620,.07,'sine'],hit:[95,.23,'sawtooth']};const n=notes[type]||notes.pop;o.type=n[2];o.frequency.setValueAtTime(n[0],now);if(type==='pop'||type==='hit')o.frequency.exponentialRampToValueAtTime(Math.max(45,n[0]*.55),now+n[1]);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(type==='fire'?.018:.045,now+.008);g.gain.exponentialRampToValueAtTime(.0001,now+n[1]);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+n[1]+.01)}catch(_){}}
document.getElementById('soundBtn').onclick=()=>{soundOn=!soundOn;document.getElementById('soundBtn').classList.toggle('active',!soundOn);document.getElementById('soundBtn').textContent=soundOn?'♫':'♪';toast(soundOn?'Sound enabled':'Sound muted')};function showModal(win){ui.overlay.classList.add('show');document.getElementById('modalIcon').textContent=win?'✦':'◈';document.getElementById('modalTitle').textContent=win?'SECTOR SECURED':'CORE BREACHED';document.getElementById('modalText').textContent=win?`All 12 waves cleared. ${kills} hostile signals eliminated. Your sector is safe — for now.`:`The signal overwhelmed your defenses at wave ${wave}. You eliminated ${kills} hostiles. Reinforce your units and try again.`;document.getElementById('modalButton').textContent=win?'PLAY AGAIN':'REDEPLOY'}function gameWin(){gameOver=true;updateUI();setTimeout(()=>showModal(true),700)}function reset(){money=420;health=100;kills=0;wave=0;active=false;paused=false;gameOver=false;selectedType=null;selectedTower=null;spawnLeft=spawned=waveSize=0;towers.length=enemies.length=shots.length=particles.length=floaters.length=0;ui.overlay.classList.remove('show');document.getElementById('pauseBtn').textContent='Ⅱ';updateUI()}
document.getElementById('modalButton').onclick=reset;window.addEventListener('keydown',e=>{if(e.key>='1'&&e.key<='5')chooseType(defs[Number(e.key)-1].id);if(e.key==='Escape'){selectedType=null;selectedTower=null;refreshSelection()}if(e.key.toLowerCase()==='p')document.getElementById('pauseBtn').click();if(e.key===' '){e.preventDefault();startWave()}});window.addEventListener('resize',resize);buildCards();resize();updateUI();requestAnimationFrame(frame);
})();
</script>
